    deny_unknown_fields
)]
enum DefinitionWire {
    Expression {
        #[serde(default)]
        recursive: bool,
        #[serde(deserialize_with = "deserialize_wire_index")]
        id: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        parameter_count: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        capture_count: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        local_scope: usize,
        body: Expression,
    },
    Action {
        #[serde(default)]
        recursive: bool,
        #[serde(deserialize_with = "deserialize_wire_index")]
        id: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        parameter_count: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        capture_count: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        local_scope: usize,
        body: Vec<Branch>,
    },
    Temporal {
        #[serde(default)]
        recursive: bool,
        #[serde(deserialize_with = "deserialize_wire_index")]
        id: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        parameter_count: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        capture_count: usize,
        #[serde(deserialize_with = "deserialize_wire_index")]
        local_scope: usize,
        body: Box<TemporalFormula>,
    },
}

impl From<DefinitionWire> for Definition {
    fn from(value: DefinitionWire) -> Self {
        match value {
            DefinitionWire::Expression {
                recursive,
                id,
                parameter_count,
                capture_count,
                local_scope,
                body,
            } => Self {
                recursive,
                id,
                parameter_count,
                capture_count,
                local_scope,
                body_kind: BodyKind::Expression,
                body: body.into(),
            },
            DefinitionWire::Action {
                recursive,
                id,
                parameter_count,
                capture_count,
                local_scope,
                body,
            } => Self {
                recursive,
                id,
                parameter_count,
                capture_count,
                local_scope,
                body_kind: BodyKind::Action,
                body: DefinitionBody::Action(body),
            },
            DefinitionWire::Temporal {
                recursive,
                id,
                parameter_count,
                capture_count,
                local_scope,
                body,
            } => Self {
                recursive,
                id,
                parameter_count,
                capture_count,
                local_scope,
                body_kind: BodyKind::Temporal,
                body: DefinitionBody::Temporal(body),
            },
        }
    }
}

