use crate::CoreError;
use crate::ir::{
    DefinitionBody, Expression, SafetyBounds, SafetyProgram, SafetyTraceStep, SafetyViolation,
    Scalar, TemporalFormula,
};
use crate::safety_expressions::{
    CallFrame, EvalContext, validate_constant_bindings, visit_bindings,
};
use crate::safety_values::Arena;
use std::collections::{HashMap, HashSet, VecDeque};
use std::sync::Arc;

impl TemporalFormula {
    pub(crate) fn validate(&self, variables: usize, depth: usize) -> Result<(), CoreError> {
        self.validate_locals(variables, depth, 0)
    }
    fn validate_locals(
        &self,
        variables: usize,
        depth: usize,
        locals: usize,
    ) -> Result<(), CoreError> {
        if depth > 40 {
            return Err(CoreError::protocol("Temporal formula nesting exceeds 40"));
        }
        match self {
            Self::Frame { .. } | Self::Call { .. } => {
                return Err(CoreError::protocol(
                    "Operator references require safety IR v2",
                ));
            }
            Self::Atom { expression } => expression.validate_locals(variables, 1, locals)?,
            Self::Not { formula } | Self::Always { formula } | Self::Eventually { formula } => {
                formula.validate_locals(variables, depth + 1, locals)?
            }
            Self::And { left, right } | Self::Or { left, right } => {
                left.validate_locals(variables, depth + 1, locals)?;
                right.validate_locals(variables, depth + 1, locals)?;
            }
            Self::Forall { bounds, formula } | Self::Exists { bounds, formula } => {
                let locals = validate_constant_bindings(bounds, variables, locals)?;
                formula.validate_locals(variables, depth + 1, locals)?;
            }
        }
        Ok(())
    }
}
#[derive(Clone, Copy)]
pub(crate) struct GraphEdge {
    pub target: usize,
    pub action: Option<usize>,
}

struct LexicalSnapshot {
    locals: Vec<Scalar>,
    frame: Option<Arc<CallFrame>>,
    old: Option<Scalar>,
}

enum Formula<'a> {
    True,
    False,
    Atom(&'a Expression, bool, LexicalSnapshot),
    And(usize, usize),
    Or(usize, usize),
    Until(usize, usize),
    Release(usize, usize),
}
struct Pool<'a> {
    formulas: Vec<Formula<'a>>,
    definitions: &'a [crate::ir::Definition],
    until: Vec<usize>,
    frame_sequence: usize,
    entries: Vec<Vec<usize>>,
    active_entries: Vec<usize>,
    lower_entered: HashSet<usize>,
}
impl<'a> Pool<'a> {
    fn add(&mut self, formula: Formula<'a>) -> usize {
        match &formula {
            Formula::And(left, right) => {
                if matches!(self.formulas[*left], Formula::False)
                    || matches!(self.formulas[*right], Formula::True)
                {
                    return *left;
                }
                if matches!(self.formulas[*right], Formula::False)
                    || matches!(self.formulas[*left], Formula::True)
                {
                    return *right;
                }
            }
            Formula::Or(left, right) => {
                if matches!(self.formulas[*left], Formula::True)
                    || matches!(self.formulas[*right], Formula::False)
                {
                    return *left;
                }
                if matches!(self.formulas[*right], Formula::True)
                    || matches!(self.formulas[*left], Formula::False)
                {
                    return *right;
                }
            }
            _ => {}
        }
        let index = self.formulas.len();
        if matches!(formula, Formula::Until(..)) {
            self.until.push(index);
        }
        self.formulas.push(formula);
        self.entries.push(self.active_entries.clone());
        index
    }
    fn lower(
        &mut self,
        formula: &'a TemporalFormula,
        negative: bool,
        context: EvalContext<'_>,
        entries: &[usize],
        arena: &mut Arena,
    ) -> Result<usize, CoreError> {
        let previous = std::mem::replace(&mut self.active_entries, entries.to_vec());
        let result = self.lower_inner(formula, negative, context, entries, arena);
        self.active_entries = previous;
        result
    }
    fn lower_inner(
        &mut self,
        formula: &'a TemporalFormula,
        negative: bool,
        mut context: EvalContext<'_>,
        entries: &[usize],
        arena: &mut Arena,
    ) -> Result<usize, CoreError> {
        context.descend(arena)?;
        arena.tick()?;
        Ok(match formula {
            TemporalFormula::Call {
                arguments,
                captures,
                definition,
            } => {
                let definitions = self.definitions;
                let DefinitionBody::Temporal(formula) = &definitions
                    .get(*definition)
                    .ok_or_else(|| CoreError::protocol("Unknown safety definition ID"))?
                    .body
                else {
                    return Err(CoreError::protocol("Invalid safety call body kind"));
                };
                let frame = CallFrame::new(arguments, captures, context);
                let mut entries = entries.to_vec();
                entries.push(self.frame_sequence);
                self.frame_sequence += 1;
                self.lower(
                    formula,
                    negative,
                    EvalContext {
                        locals: &[],
                        frame: Some(&frame),
                        old: None,
                        ..context
                    },
                    &entries,
                    arena,
                )?
            }
            TemporalFormula::Frame {
                arguments,
                captures,
                formula,
                ..
            } => {
                let frame = CallFrame::new(arguments, captures, context);
                let mut entries = entries.to_vec();
                entries.push(self.frame_sequence);
                self.frame_sequence += 1;
                self.lower(
                    formula,
                    negative,
                    EvalContext {
                        locals: &[],
                        frame: Some(&frame),
                        old: None,
                        ..context
                    },
                    &entries,
                    arena,
                )?
            }
            TemporalFormula::Atom { expression } => self.add(Formula::Atom(
                expression,
                negative,
                LexicalSnapshot {
                    locals: context.locals.to_vec(),
                    frame: context.frame.cloned().map(Arc::new),
                    old: context.old,
                },
            )),
            TemporalFormula::Not { formula } => {
                self.lower(formula, !negative, context, entries, arena)?
            }
            TemporalFormula::And { left, right } | TemporalFormula::Or { left, right } => {
                let left = self.lower(left, negative, context, entries, arena)?;
                let right = self.lower(right, negative, context, entries, arena)?;
                if matches!(formula, TemporalFormula::And { .. }) != negative {
                    self.add(Formula::And(left, right))
                } else {
                    self.add(Formula::Or(left, right))
                }
            }
            TemporalFormula::Always { formula: inner }
            | TemporalFormula::Eventually { formula: inner } => {
                let child = self.lower(inner, negative, context, entries, arena)?;
                if matches!(formula, TemporalFormula::Eventually { .. }) != negative {
                    let truth = self.add(Formula::True);
                    self.add(Formula::Until(truth, child))
                } else {
                    let falsity = self.add(Formula::False);
                    self.add(Formula::Release(falsity, child))
                }
            }
            TemporalFormula::Forall {
                bounds,
                formula: inner,
            }
            | TemporalFormula::Exists {
                bounds,
                formula: inner,
            } => {
                let conjunction = matches!(formula, TemporalFormula::Forall { .. }) != negative;
                let mut result = self.add(if conjunction {
                    Formula::True
                } else {
                    Formula::False
                });
                for entry in entries {
                    if self.lower_entered.insert(*entry) {
                        arena.consume(1)?;
                    }
                }
                visit_bindings(bounds, 0, context, arena, &mut |ctx, arena| {
                    let child = self.lower(inner, negative, ctx, entries, arena)?;
                    result = self.add(if conjunction {
                        Formula::And(result, child)
                    } else {
                        Formula::Or(result, child)
                    });
                    Ok(true)
                })?;
                result
            }
        })
    }
}
#[derive(Clone)]
enum Seen {
    Dense([u64; 4]),
    Sparse(HashSet<usize>),
}
impl Seen {
    fn new(formulas: usize) -> Self {
        if formulas <= 256 {
            Self::Dense([0; 4])
        } else {
            Self::Sparse(HashSet::new())
        }
    }
    fn insert(&mut self, id: usize) -> bool {
        match self {
            Self::Dense(words) => {
                let word = &mut words[id / 64];
                let mask = 1 << (id % 64);
                let fresh = *word & mask == 0;
                *word |= mask;
                fresh
            }
            Self::Sparse(set) => set.insert(id),
        }
    }
    fn contains(&self, id: usize) -> bool {
        match self {
            Self::Dense(words) => words[id / 64] & (1 << (id % 64)) != 0,
            Self::Sparse(set) => set.contains(&id),
        }
    }
}
#[derive(Clone)]
struct Expansion {
    todo: Vec<usize>,
    seen: Seen,
    entered: HashSet<usize>,
    next: Vec<usize>,
    pending: Vec<usize>,
}
struct Alternative {
    next: Vec<usize>,
    pending: Vec<usize>,
}
fn expand(
    pool: &Pool<'_>,
    required: &[usize],
    ctx: EvalContext<'_>,
    arena: &mut Arena,
) -> Result<Vec<Alternative>, CoreError> {
    let mut stack = vec![Expansion {
        todo: required.to_vec(),
        seen: Seen::new(pool.formulas.len()),
        entered: HashSet::new(),
        next: vec![],
        pending: vec![],
    }];
    let mut result = vec![];
    'alternative: while let Some(mut state) = stack.pop() {
        while let Some(id) = state.todo.pop() {
            arena.tick()?;
            if !state.seen.insert(id) {
                continue;
            }
            for entry in &pool.entries[id] {
                if state.entered.insert(*entry) {
                    arena.consume(1)?;
                }
            }
            match &pool.formulas[id] {
                Formula::True => {}
                Formula::False => continue 'alternative,
                Formula::Atom(expression, negative, lexical) => {
                    if expression
                        .eval(
                            EvalContext {
                                locals: &lexical.locals,
                                frame: lexical.frame.as_deref(),
                                old: lexical.old,
                                ..ctx
                            },
                            arena,
                        )?
                        .boolean()?
                        == *negative
                    {
                        continue 'alternative;
                    }
                }
                Formula::And(left, right) => {
                    state.todo.push(*right);
                    state.todo.push(*left);
                }
                Formula::Or(left, right) => {
                    let mut other = state.clone();
                    other.todo.push(*right);
                    stack.push(other);
                    state.todo.push(*left);
                }
                Formula::Until(left, right) => {
                    let mut other = state.clone();
                    other.todo.push(*left);
                    other.next.push(id);
                    other.pending.push(id);
                    stack.push(other);
                    state.todo.push(*right);
                }
                Formula::Release(left, right) => {
                    let mut other = state.clone();
                    other.todo.push(*right);
                    other.next.push(id);
                    stack.push(other);
                    state.todo.push(*right);
                    state.todo.push(*left);
                }
            }
        }
        state.next.sort_unstable();
        state.next.dedup();
        state.pending.retain(|id| match pool.formulas[*id] {
            Formula::Until(_, right) => !state.seen.contains(right),
            _ => false,
        });
        state.pending.sort_unstable();
        state.pending.dedup();
        result.push(Alternative {
            next: state.next,
            pending: state.pending,
        });
    }
    Ok(result)
}
#[derive(Clone)]
struct ProductEdge {
    target: usize,
    action: Option<usize>,
    pending: Vec<usize>,
}
struct ProductNode {
    state: usize,
    required: Vec<usize>,
    parent: Option<(usize, usize)>,
}
struct Cycle {
    entry: usize,
    edges: Vec<(usize, usize)>,
}
struct Product<'a> {
    pool: Pool<'a>,
    nodes: Vec<ProductNode>,
    edges: Vec<Vec<ProductEdge>>,
    lookup: HashMap<(usize, Vec<usize>), usize>,
    maximum: usize,
}
impl Product<'_> {
    fn node(
        &mut self,
        state: usize,
        required: Vec<usize>,
        parent: Option<(usize, usize)>,
    ) -> Result<usize, CoreError> {
        if let Some(index) = self.lookup.get(&(state, required.clone())) {
            return Ok(*index);
        }
        if self.nodes.len() == self.maximum {
            return Err(CoreError {
                code: "temporal-budget",
                message: "Temporal product node budget exhausted".into(),
            });
        }
        let index = self.nodes.len();
        self.lookup.insert((state, required.clone()), index);
        self.nodes.push(ProductNode {
            state,
            required,
            parent,
        });
        self.edges.push(vec![]);
        Ok(index)
    }
    fn components(&self, arena: &mut Arena) -> Result<Vec<Vec<usize>>, CoreError> {
        let mut visited = vec![false; self.nodes.len()];
        let mut order = vec![];
        for root in 0..self.nodes.len() {
            if visited[root] {
                continue;
            }
            visited[root] = true;
            let mut stack = vec![(root, 0)];
            while let Some((node, position)) = stack.last_mut() {
                arena.tick()?;
                if let Some(edge) = self.edges[*node].get(*position) {
                    *position += 1;
                    if !visited[edge.target] {
                        visited[edge.target] = true;
                        stack.push((edge.target, 0));
                    }
                } else {
                    order.push(*node);
                    stack.pop();
                }
            }
        }
        let mut reverse = vec![vec![]; self.nodes.len()];
        for (source, edges) in self.edges.iter().enumerate() {
            for edge in edges {
                arena.tick()?;
                reverse[edge.target].push(source);
            }
        }
        visited.fill(false);
        let mut components = vec![];
        for root in order.into_iter().rev() {
            if visited[root] {
                continue;
            }
            visited[root] = true;
            let mut component = vec![];
            let mut stack = vec![root];
            while let Some(node) = stack.pop() {
                arena.tick()?;
                component.push(node);
                for parent in &reverse[node] {
                    if !visited[*parent] {
                        visited[*parent] = true;
                        stack.push(*parent);
                    }
                }
            }
            component.sort_unstable();
            components.push(component);
        }
        Ok(components)
    }
    fn path(
        &self,
        start: usize,
        end: usize,
        members: &HashSet<usize>,
        arena: &mut Arena,
    ) -> Result<Vec<(usize, usize)>, CoreError> {
        if start == end {
            return Ok(vec![]);
        }
        let mut queue = VecDeque::from([start]);
        let mut parents = HashMap::from([(start, None)]);
        while let Some(source) = queue.pop_front() {
            arena.tick()?;
            for (index, edge) in self.edges[source].iter().enumerate() {
                if members.contains(&edge.target) && !parents.contains_key(&edge.target) {
                    parents.insert(edge.target, Some((source, index)));
                    if edge.target == end {
                        let mut path = vec![];
                        let mut node = end;
                        while let Some(Some((source, index))) = parents.get(&node) {
                            path.push((*source, *index));
                            node = *source;
                        }
                        path.reverse();
                        return Ok(path);
                    }
                    queue.push_back(edge.target);
                }
            }
        }
        Err(CoreError::protocol("Broken temporal component"))
    }
    fn accepting_cycle(&self, arena: &mut Arena) -> Result<Option<Cycle>, CoreError> {
        for component in self.components(arena)? {
            let entry = component[0];
            let members: HashSet<_> = component.iter().copied().collect();
            if component.len() == 1 && !self.edges[entry].iter().any(|edge| edge.target == entry) {
                continue;
            }
            let mut selected = vec![];
            let mut accepting = true;
            for until in &self.pool.until {
                let mut witness = None;
                'find: for source in &component {
                    for (index, edge) in self.edges[*source].iter().enumerate() {
                        arena.tick()?;
                        if members.contains(&edge.target) && !edge.pending.contains(until) {
                            witness = Some((*source, index));
                            break 'find;
                        }
                    }
                }
                if let Some(edge) = witness {
                    selected.push(edge);
                } else {
                    accepting = false;
                    break;
                }
            }
            if !accepting {
                continue;
            }
            if selected.is_empty() {
                let Some(index) = self.edges[entry]
                    .iter()
                    .position(|edge| members.contains(&edge.target))
                else {
                    continue;
                };
                selected.push((entry, index));
            }
            let mut current = entry;
            let mut cycle = vec![];
            for (source, index) in selected {
                cycle.extend(self.path(current, source, &members, arena)?);
                cycle.push((source, index));
                current = self.edges[source][index].target;
            }
            cycle.extend(self.path(current, entry, &members, arena)?);
            return Ok(Some(Cycle {
                entry,
                edges: cycle,
            }));
        }
        Ok(None)
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn check(
    program: &SafetyProgram,
    bounds: SafetyBounds,
    values: &[Scalar],
    width: usize,
    graph: &[Vec<GraphEdge>],
    roots: &[usize],
    arena: &mut Arena,
) -> Result<Option<SafetyViolation>, CoreError> {
    for property in &program.properties {
        let mut pool = Pool {
            definitions: program.definitions.as_deref().unwrap_or_default(),
            formulas: vec![],
            until: vec![],
            frame_sequence: 0,
            entries: vec![],
            active_entries: vec![],
            lower_entered: HashSet::new(),
        };
        let mut root = pool.lower(
            &property.formula,
            true,
            EvalContext::new(&[], &[]),
            &[],
            arena,
        )?;
        for fairness in &program.fairness {
            let fairness = pool.lower(fairness, false, EvalContext::new(&[], &[]), &[], arena)?;
            root = pool.add(Formula::And(fairness, root));
        }
        if matches!(pool.formulas[root], Formula::False) {
            return Err(CoreError::protocol(
                "Temporal formula is a tautology (its negation is unsatisfiable)",
            ));
        }
        let mut product = Product {
            pool,
            nodes: vec![],
            edges: vec![],
            lookup: HashMap::new(),
            maximum: bounds.max_temporal_nodes.unwrap_or(bounds.max_states) as usize,
        };
        for state in roots {
            product.node(*state, vec![root], None)?;
        }
        let mut index = 0;
        while index < product.nodes.len() {
            arena.tick()?;
            let source = product.nodes[index].state;
            let required = product.nodes[index].required.clone();
            for edge in &graph[source] {
                let current = &values[source * width..(source + 1) * width];
                let next: Vec<_> = values[edge.target * width..(edge.target + 1) * width]
                    .iter()
                    .copied()
                    .map(Some)
                    .collect();
                for alternative in expand(
                    &product.pool,
                    &required,
                    EvalContext::new(current, &next),
                    arena,
                )? {
                    arena.tick()?;
                    let ordinal = product.edges[index].len();
                    let target =
                        product.node(edge.target, alternative.next, Some((index, ordinal)))?;
                    product.edges[index].push(ProductEdge {
                        target,
                        action: edge.action,
                        pending: alternative.pending,
                    });
                }
            }
            index += 1;
        }
        if let Some(cycle) = product.accepting_cycle(arena)? {
            let entry = cycle.entry;
            let cycle = cycle.edges;
            let mut prefix = vec![];
            let mut current = entry;
            while let Some((source, index)) = product.nodes[current].parent {
                prefix.push((source, index));
                current = source;
            }
            prefix.reverse();
            let mut trace = vec![SafetyTraceStep {
                action: None,
                values: values[product.nodes[current].state * width
                    ..(product.nodes[current].state + 1) * width]
                    .iter()
                    .map(|value| arena.portable(*value))
                    .collect::<Result<_, _>>()?,
            }];
            let label = |action: Option<usize>| {
                action
                    .map(|index| program.next[index].name.clone())
                    .unwrap_or_else(|| "<stuttering>".into())
            };
            for (source, index) in &prefix {
                let edge = &product.edges[*source][*index];
                let state = product.nodes[edge.target].state;
                trace.push(SafetyTraceStep {
                    action: Some(label(edge.action)),
                    values: values[state * width..(state + 1) * width]
                        .iter()
                        .map(|value| arena.portable(*value))
                        .collect::<Result<_, _>>()?,
                });
            }
            let loop_start = trace.len() - 1;
            for (source, index) in cycle.iter().take(cycle.len() - 1) {
                let edge = &product.edges[*source][*index];
                let state = product.nodes[edge.target].state;
                trace.push(SafetyTraceStep {
                    action: Some(label(edge.action)),
                    values: values[state * width..(state + 1) * width]
                        .iter()
                        .map(|value| arena.portable(*value))
                        .collect::<Result<_, _>>()?,
                });
            }
            let (source, index) = cycle[cycle.len() - 1];
            return Ok(Some(SafetyViolation {
                name: property.name.clone(),
                trace,
                loop_start: Some(loop_start),
                loop_action: Some(label(product.edges[source][index].action)),
            }));
        }
    }
    Ok(None)
}

use crate::ir::{Branch, Domain, Expression, SafetyProgram, Scalar, Step};
use crate::safety_expressions::{EvalContext, visit_branch};
use crate::safety_values::Arena;
use crate::{CoreError, Value};
use std::collections::{HashMap, HashSet};
use std::hash::{DefaultHasher, Hash, Hasher};

struct Representative {
    values: Box<[Scalar]>,
    index: usize,
}

struct NodeRows {
    header: Vec<Scalar>,
    values: Vec<Scalar>,
    columns: usize,
}

pub(crate) struct Symmetry {
    group: Vec<Scalar>,
    keys: HashMap<u64, Vec<Representative>>,
}

impl Symmetry {
    pub fn action_members(
        &self,
        branch: &Branch,
        context: EvalContext<'_>,
        arena: &mut Arena,
    ) -> Result<Option<Vec<Scalar>>, CoreError> {
        if let [
            Step::Bind {
                slot: 0,
                domain,
                tuple_size: None,
            },
            rest @ ..,
        ] = branch.steps.as_slice()
            && !rest.iter().any(|step| matches!(step, Step::Bind { .. }))
        {
            let values: Vec<_> = domain.values(context, arena)?.collect();
            return self
                .representatives(context.current, &values, arena)
                .map(Some);
        }
        Ok(None)
    }
    pub fn prepare(program: &SafetyProgram, arena: &mut Arena) -> Result<Self, CoreError> {
        let definition = program.symmetry.as_ref().unwrap();
        if program.version != 1 {
            return Err(CoreError::protocol("Unsupported symmetry: safety IR v2"));
        }
        let mut names = definition.model_values.clone();
        names.sort();
        if !(2..=64).contains(&names.len())
            || names.iter().collect::<HashSet<_>>().len() != names.len()
            || names.iter().any(|name| {
                name.as_bytes().get(1) == Some(&b'_')
                    || Value::ModelValue(name.clone()).normalize().is_err()
            })
        {
            return Err(CoreError::protocol(
                "Unsupported symmetry: expected 2 to 64 distinct untyped model values",
            ));
        }
        if !program.properties.is_empty()
            || !program.fairness.is_empty()
            || !program.constraints.is_empty()
            || !program.action_constraints.is_empty()
            || !program.initial_properties.is_empty()
            || !program.action_properties.is_empty()
        {
            return Err(CoreError::protocol(
                "Unsupported symmetry: only unconstrained safety invariants and deadlock",
            ));
        }
        let mut expressions = Vec::new();
        for branch in program.initial.iter().chain(&program.next) {
            for step in &branch.steps {
                match step {
                    Step::Guard { expression }
                    | Step::Assign {
                        value: expression, ..
                    } => expressions.push(expression),
                    Step::Bind { domain, .. } | Step::Choose { domain, .. } => {
                        domain_roots(domain, &names, &mut expressions)
                    }
                    Step::Frame { .. } | Step::Call { .. } => {
                        return Err(CoreError::protocol("Unsupported symmetry: lexical frame"));
                    }
                }
            }
        }
        expressions.extend(
            program
                .invariants
                .iter()
                .chain(&program.assumptions)
                .map(|predicate| &predicate.expression),
        );
        while let Some(expression) = expressions.pop() {
            if node_set(expression, &names) {
                continue;
            }
            match expression {
                Expression::Data { value } => {
                    let mut values = vec![value];
                    while let Some(value) = values.pop() {
                        match value {
                            Value::ModelValue(_) => {
                                return Err(CoreError::protocol(
                                    "Unsupported symmetry: individual model value reference",
                                ));
                            }
                            Value::Set(items) | Value::List(items) => values.extend(items),
                            Value::Record(fields) => {
                                values.extend(fields.iter().map(|(_, value)| value))
                            }
                            Value::Map(entries) => {
                                values.extend(entries.iter().flat_map(|(key, value)| [key, value]))
                            }
                            _ => {}
                        }
                    }
                }
                Expression::Literal {
                    value: Scalar::Ref(_),
                }
                | Expression::Choose { .. }
                | Expression::Fold { .. }
                | Expression::SelectSeq { .. }
                | Expression::SortSeq { .. }
                | Expression::Enabled { .. }
                | Expression::UnmatchedCase { .. }
                | Expression::Assert { .. }
                | Expression::VariantTag { .. }
                | Expression::Head { .. }
                | Expression::Tail { .. }
                | Expression::Subseq { .. }
                | Expression::SequenceSet { .. }
                | Expression::SequenceIn { .. }
                | Expression::Append { .. }
                | Expression::Concat { .. }
                | Expression::Len { .. } => {
                    return Err(CoreError::protocol(
                        "Unsupported symmetry: order-sensitive or unsupported expression",
                    ));
                }
                Expression::Forall { bounds, body }
                | Expression::Exists { bounds, body }
                | Expression::Function { bounds, body }
                | Expression::Filter { bounds, body }
                | Expression::MapSet { bounds, body } => {
                    for bound in bounds {
                        domain_roots(&bound.domain, &names, &mut expressions);
                    }
                    expressions.push(body);
                    continue;
                }
                Expression::In { value, domain } => {
                    expressions.push(value);
                    domain_roots(domain, &names, &mut expressions);
                    continue;
                }
                _ => {}
            }
            expressions.extend(expression.children());
        }
        let group = names
            .into_iter()
            .map(|name| arena.data(&Value::ModelValue(name)))
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Self {
            group,
            keys: HashMap::new(),
        })
    }

    pub fn key(
        &self,
        values: &[Option<Scalar>],
        arena: &mut Arena,
    ) -> Result<Vec<Scalar>, CoreError> {
        let mut rows = self.rows(values.iter().copied(), arena)?;
        if rows.columns != 0 {
            arena.consume(self.group.len() * self.group.len() * rows.columns)?;
            let mut order = (0..self.group.len()).collect::<Vec<_>>();
            order.sort_unstable_by(|left, right| {
                rows.values[*left * rows.columns..(*left + 1) * rows.columns]
                    .cmp(&rows.values[*right * rows.columns..(*right + 1) * rows.columns])
            });
            for index in order {
                rows.header.extend_from_slice(
                    &rows.values[index * rows.columns..(index + 1) * rows.columns],
                );
            }
        }
        Ok(rows.header)
    }

    pub fn representatives(
        &self,
        current: &[Scalar],
        members: &[Scalar],
        arena: &mut Arena,
    ) -> Result<Vec<Scalar>, CoreError> {
        if members != self.group {
            return Ok(members.to_vec());
        }
        let rows = self.rows(current.iter().copied().map(Some), arena)?;
        if rows.columns == 0 {
            return Ok(self.group.first().copied().into_iter().collect());
        }
        let mut seen = HashSet::new();
        Ok(self
            .group
            .iter()
            .copied()
            .zip(rows.values.chunks_exact(rows.columns))
            .filter_map(|(member, row)| seen.insert(row).then_some(member))
            .collect())
    }

    fn rows(
        &self,
        values: impl Clone + ExactSizeIterator<Item = Option<Scalar>>,
        arena: &mut Arena,
    ) -> Result<NodeRows, CoreError> {
        arena.consume(values.len())?;
        let mut key = Vec::with_capacity(values.len());
        let columns = values
            .clone()
            .filter(|value| matches!(value, Some(Scalar::Ref(_))))
            .count();
        let mut rows = vec![Scalar::Bool(false); self.group.len() * columns];
        let mut column = 0;
        for value in values {
            match value.ok_or_else(|| CoreError::protocol("Incomplete safety state"))? {
                value @ (Scalar::Bool(_) | Scalar::Int(_)) => key.push(value),
                value @ Scalar::Ref(_) => {
                    arena.consume(self.group.len())?;
                    if let Ok(members) = arena.members(value) {
                        if members.iter().any(|member| !self.group.contains(member)) {
                            return Err(CoreError::protocol(
                                "Unsupported symmetry: set contains a non-node value",
                            ));
                        }
                        for (index, member) in self.group.iter().enumerate() {
                            rows[index * columns + column] = Scalar::Bool(members.contains(member));
                        }
                        column += 1;
                        key.push(Scalar::Ref(1));
                        continue;
                    }
                    let entries = arena.entries(value).map_err(|_| CoreError::protocol("Unsupported symmetry: state must contain scalar node functions or Int/Bool"))?;
                    if entries.len() != self.group.len()
                        || !entries
                            .iter()
                            .zip(&self.group)
                            .all(|((key, _), member)| key == member)
                        || !entries.iter().all(|(_, value)| {
                            std::mem::discriminant(value) == std::mem::discriminant(&entries[0].1)
                        })
                    {
                        return Err(CoreError::protocol(
                            "Unsupported symmetry: node function needs the complete domain and homogeneous payload",
                        ));
                    }
                    if matches!(entries[0].1, Scalar::Ref(_)) {
                        let shape = arena.scalar_record_shape(entries[0].1)?;
                        for (_, record) in &entries {
                            arena.consume(shape.len())?;
                            if *record != entries[0].1
                                && arena.scalar_record_shape(*record)? != shape
                            {
                                return Err(CoreError::protocol(
                                    "Unsupported symmetry: record schema and field types must agree",
                                ));
                            }
                        }
                    }
                    for (index, (_, value)) in entries.into_iter().enumerate() {
                        rows[index * columns + column] = value;
                    }
                    column += 1;
                    key.push(Scalar::Ref(0));
                }
            }
        }
        Ok(NodeRows {
            header: key,
            values: rows,
            columns,
        })
    }

    pub fn hash(key: &[Scalar]) -> u64 {
        let mut hash = DefaultHasher::new();
        key.hash(&mut hash);
        hash.finish()
    }

    pub fn find(&self, hash: u64, key: &[Scalar]) -> Option<usize> {
        self.keys
            .get(&hash)?
            .iter()
            .find_map(|stored| (stored.values.as_ref() == key).then_some(stored.index))
    }

    pub fn insert(&mut self, hash: u64, key: Vec<Scalar>, index: usize) {
        self.keys.entry(hash).or_default().push(Representative {
            values: key.into_boxed_slice(),
            index,
        });
    }
}

pub(crate) fn visit_representatives(
    branch: &Branch,
    context: EvalContext<'_>,
    next: &mut [Option<Scalar>],
    arena: &mut Arena,
    members: &[Scalar],
    visitor: &mut impl FnMut(&[Option<Scalar>], &mut Arena) -> Result<bool, CoreError>,
) -> Result<bool, CoreError> {
    arena.tick()?;
    for member in members {
        if visit_branch(
            branch,
            1,
            EvalContext {
                locals: &[*member],
                ..context
            },
            next,
            arena,
            &mut |values, arena| visitor(values, arena),
        )? {
            return Ok(true);
        }
    }
    Ok(false)
}

fn node_members<'a>(values: impl Iterator<Item = Option<&'a str>>, names: &[String]) -> bool {
    let Some(mut values) = values
        .map(|value| value.map(str::to_owned))
        .collect::<Option<Vec<_>>>()
    else {
        return false;
    };
    values.sort();
    values == names
}

fn node_set(expression: &Expression, names: &[String]) -> bool {
    match expression {
        Expression::Set { values } => node_members(
            values.iter().map(|value| match value {
                Expression::Data {
                    value: Value::ModelValue(name),
                } => Some(name.as_str()),
                _ => None,
            }),
            names,
        ),
        Expression::Data {
            value: Value::Set(values),
        } => node_members(
            values.iter().map(|value| match value {
                Value::ModelValue(name) => Some(name.as_str()),
                _ => None,
            }),
            names,
        ),
        _ => false,
    }
}

fn domain_roots<'a>(domain: &'a Domain, names: &[String], expressions: &mut Vec<&'a Expression>) {
    if let Domain::Set { values } = domain
        && node_members(
            values.iter().map(|value| match value {
                Expression::Data {
                    value: Value::ModelValue(name),
                } => Some(name.as_str()),
                _ => None,
            }),
            names,
        )
    {
        return;
    }
    expressions.extend(domain.children());
}

#[cfg(test)]
mod tests {
    use super::Symmetry;
    use crate::Value;
    use crate::ir::Scalar;
    use crate::safety_values::Arena;
    use std::collections::HashMap;

    fn symmetry(arena: &mut Arena) -> Symmetry {
        Symmetry {
            group: ["a", "b"]
                .into_iter()
                .map(|name| arena.data(&Value::ModelValue(name.into())).unwrap())
                .collect(),
            keys: HashMap::new(),
        }
    }
    fn function(arena: &mut Arena, symmetry: &Symmetry, values: [Scalar; 2]) -> Scalar {
        arena
            .function(symmetry.group.iter().copied().zip(values).collect())
            .unwrap()
    }

    #[test]
    fn joint_rows_preserve_correlations_global_values_and_variable_positions() {
        let mut arena = Arena::new(10000);
        let symmetry = symmetry(&mut arena);
        let forward = function(&mut arena, &symmetry, [Scalar::Int(0), Scalar::Int(1)]);
        let reverse = function(&mut arena, &symmetry, [Scalar::Int(1), Scalar::Int(0)]);
        let actual = symmetry
            .key(
                &[Some(forward), Some(forward), Some(Scalar::Bool(false))],
                &mut arena,
            )
            .unwrap();
        assert_eq!(
            actual,
            symmetry
                .key(
                    &[Some(reverse), Some(reverse), Some(Scalar::Bool(false))],
                    &mut arena
                )
                .unwrap()
        );
        assert_ne!(
            actual,
            symmetry
                .key(
                    &[Some(forward), Some(reverse), Some(Scalar::Bool(false))],
                    &mut arena
                )
                .unwrap()
        );
        assert_ne!(
            actual,
            symmetry
                .key(
                    &[Some(forward), Some(forward), Some(Scalar::Bool(true))],
                    &mut arena
                )
                .unwrap()
        );
        assert_ne!(
            actual,
            symmetry
                .key(
                    &[Some(Scalar::Bool(false)), Some(forward), Some(forward)],
                    &mut arena
                )
                .unwrap()
        );
    }

    #[test]
    fn scalar_only_states_keep_the_first_node_as_representative() {
        let mut arena = Arena::new(100);
        let symmetry = symmetry(&mut arena);
        let current = [Scalar::Int(4), Scalar::Bool(true)];
        assert_eq!(
            symmetry
                .representatives(&current, &symmetry.group, &mut arena)
                .unwrap(),
            vec![symmetry.group[0]]
        );
        assert_eq!(
            symmetry.key(&current.map(Some), &mut arena).unwrap(),
            current
        );
        let before = arena.work;
        let error = symmetry
            .key(&[Some(Scalar::Int(4)), None], &mut arena)
            .unwrap_err();
        assert_eq!(error.code, "protocol");
        assert_eq!(error.message, "Incomplete safety state");
        assert_eq!(arena.work - before, 2);
    }

    #[test]
    fn identical_records_keep_canonical_and_representative_work() {
        let mut arena = Arena::new(1000);
        let symmetry = symmetry(&mut arena);
        let ready = arena.string("ready".into()).unwrap();
        let term = arena.string("term".into()).unwrap();
        let record = arena
            .function(vec![(ready, Scalar::Bool(false)), (term, Scalar::Int(1))])
            .unwrap();
        let nodes = function(&mut arena, &symmetry, [record, record]);
        let before = arena.work;
        let key = symmetry.key(&[Some(nodes)], &mut arena).unwrap();
        assert_eq!(arena.work - before, 11);
        let before = arena.work;
        assert_eq!(
            symmetry
                .representatives(&[nodes], &symmetry.group, &mut arena)
                .unwrap(),
            vec![symmetry.group[0]]
        );
        assert_eq!(arena.work - before, 7);
        assert_eq!(symmetry.key(&[Some(nodes)], &mut arena).unwrap(), key);
    }

    #[test]
    fn row_storage_does_not_change_canonical_work() {
        let mut arena = Arena::new(100);
        let symmetry = symmetry(&mut arena);
        let forward = function(&mut arena, &symmetry, [Scalar::Int(0), Scalar::Int(1)]);
        let reverse = function(&mut arena, &symmetry, [Scalar::Int(1), Scalar::Int(0)]);
        let before = arena.work;
        symmetry
            .key(
                &[Some(forward), Some(Scalar::Bool(false)), Some(reverse)],
                &mut arena,
            )
            .unwrap();
        assert_eq!(arena.work - before, 15);
    }

    #[test]
    fn colliding_canonical_hashes_use_the_complete_key() {
        let mut arena = Arena::new(100);
        let mut symmetry = symmetry(&mut arena);
        symmetry.insert(0, vec![Scalar::Int(1)], 7);
        symmetry.insert(0, vec![Scalar::Int(2)], 8);
        assert_eq!(symmetry.find(0, &[Scalar::Int(1)]), Some(7));
        assert_eq!(symmetry.find(0, &[Scalar::Int(2)]), Some(8));
        assert_eq!(symmetry.find(0, &[Scalar::Bool(true)]), None);
        assert_eq!(symmetry.find(0, &[Scalar::Int(1), Scalar::Int(2)]), None);
    }

    #[test]
    fn records_and_node_sets_preserve_joint_membership_and_schema() {
        let mut arena = Arena::new(10000);
        let symmetry = symmetry(&mut arena);
        let records: Vec<_> = [0, 1]
            .into_iter()
            .map(|number| {
                arena
                    .data(&Value::Record(vec![
                        ("term".into(), Value::Int(number.to_string())),
                        ("ready".into(), Value::Bool(false)),
                    ]))
                    .unwrap()
            })
            .collect();
        let forward = function(&mut arena, &symmetry, [records[0], records[1]]);
        let reverse = function(&mut arena, &symmetry, [records[1], records[0]]);
        let first = arena.set(vec![symmetry.group[0]]).unwrap();
        let second = arena.set(vec![symmetry.group[1]]).unwrap();
        let key = symmetry
            .key(&[Some(forward), Some(first)], &mut arena)
            .unwrap();
        assert_eq!(
            key,
            symmetry
                .key(&[Some(reverse), Some(second)], &mut arena)
                .unwrap()
        );
        assert_ne!(
            key,
            symmetry
                .key(&[Some(forward), Some(second)], &mut arena)
                .unwrap()
        );
        let renamed = arena
            .data(&Value::Record(vec![
                ("other".into(), Value::Int("0".into())),
                ("ready".into(), Value::Bool(false)),
            ]))
            .unwrap();
        let renamed = function(&mut arena, &symmetry, [renamed, renamed]);
        assert_ne!(
            symmetry.key(&[Some(forward)], &mut arena).unwrap(),
            symmetry.key(&[Some(renamed)], &mut arena).unwrap()
        );
        let outsider = arena.string("a".into()).unwrap();
        let invalid = arena.set(vec![outsider]).unwrap();
        assert!(symmetry.key(&[Some(invalid)], &mut arena).is_err());
        let pointer = arena
            .data(&Value::Record(vec![(
                "peer".into(),
                Value::ModelValue("a".into()),
            )]))
            .unwrap();
        let pointer = function(&mut arena, &symmetry, [pointer, pointer]);
        assert!(symmetry.key(&[Some(pointer)], &mut arena).is_err());
        let mixed = function(&mut arena, &symmetry, [records[0], records[1]]);
        assert!(symmetry.key(&[Some(mixed)], &mut arena).is_ok());
    }

    #[test]
    fn unsupported_shapes_and_incomplete_keys_are_errors() {
        let mut arena = Arena::new(10000);
        let symmetry = symmetry(&mut arena);
        let missing = arena
            .function(vec![(symmetry.group[0], Scalar::Int(0))])
            .unwrap();
        let mixed = function(&mut arena, &symmetry, [Scalar::Int(0), Scalar::Bool(false)]);
        let nested = function(
            &mut arena,
            &symmetry,
            [symmetry.group[0], symmetry.group[1]],
        );
        let name = arena.string("a".into()).unwrap();
        let strings = arena
            .function(vec![
                (name, Scalar::Int(0)),
                (symmetry.group[1], Scalar::Int(0)),
            ])
            .unwrap();
        for value in [
            Some(missing),
            Some(mixed),
            Some(nested),
            Some(name),
            Some(strings),
            Some(symmetry.group[0]),
            None,
        ] {
            assert_eq!(
                symmetry.key(&[value], &mut arena).unwrap_err().code,
                "protocol"
            );
        }
        let mut exhausted = Arena::new(0);
        assert_eq!(
            symmetry
                .key(&[Some(Scalar::Int(0))], &mut exhausted)
                .unwrap_err()
                .code,
            "budget"
        );
    }
}

