struct Snapshot {
    current: Vec<Scalar>,
    next: Vec<Option<Scalar>>,
    locals: Vec<Scalar>,
    old: Option<Scalar>,
    prime: bool,
    frame: Option<Arc<CallFrame>>,
    evaluation_depth: u8,
    recursive: bool,
}

impl Snapshot {
    fn new(context: EvalContext<'_>) -> Self {
        Self {
            current: context.current.to_vec(),
            next: context.next.to_vec(),
            locals: context.locals.to_vec(),
            old: context.old,
            prime: context.prime,
            frame: context.frame.cloned().map(Arc::new),
            evaluation_depth: context.evaluation_depth,
            recursive: context.recursive,
        }
    }

    fn context(&self) -> EvalContext<'_> {
        EvalContext {
            current: &self.current,
            next: &self.next,
            locals: &self.locals,
            old: self.old,
            prime: self.prime,
            frame: self.frame.as_deref(),
            evaluation_depth: self.evaluation_depth,
            recursive: self.recursive,
        }
    }
}

pub(super) enum FunctionValue {
    Scalar(Scalar),
    Lazy(Box<LazyFunction>),
    Composite(Vec<(Scalar, FunctionValue)>),
}

pub(super) struct LazyFunction {
    domains: Vec<(Values, Option<usize>)>,
    body: Arc<Expression>,
    snapshot: Snapshot,
}

impl Expression {
    pub(super) fn eval_function(
        &self,
        mut context: EvalContext<'_>,
        arena: &mut Arena,
    ) -> Result<FunctionValue, CoreError> {
        match self {
            Self::At { target, key } => {
                context.descend(arena)?;
                let target = target.eval_function(context, arena)?;
                let key = key.eval(context, arena)?;
                target.select(key, arena)
            }
            Self::Record { fields } => {
                context.descend(arena)?;
                let mut values = vec![];
                for (name, value) in fields {
                    arena.tick()?;
                    let name = arena.string(name.clone())?;
                    values.push((name, value.eval_function(context, arena)?));
                }
                Ok(FunctionValue::Composite(values))
            }
            Self::Tuple { values } => {
                context.descend(arena)?;
                let mut result = vec![];
                for (index, value) in values.iter().enumerate() {
                    arena.tick()?;
                    let key = Scalar::Int(
                        i32::try_from(index + 1)
                            .map_err(|_| CoreError::protocol("Sequence length overflow"))?,
                    );
                    result.push((key, value.eval_function(context, arena)?));
                }
                Ok(FunctionValue::Composite(result))
            }
            Self::Frame { .. }
            | Self::Call { .. }
            | Self::Parameter { .. }
            | Self::Capture { .. } => {
                context.descend(arena)?;
                self.eval_reference(context, arena, Self::eval_function)
            }
            Self::Prime { argument } => {
                context.descend(arena)?;
                argument.eval_function(
                    EvalContext {
                        prime: true,
                        ..context
                    },
                    arena,
                )
            }
            Self::If {
                condition,
                consequent,
                alternative,
            } => {
                context.descend(arena)?;
                if condition.eval(context, arena)?.boolean()? {
                    consequent
                } else {
                    alternative
                }
                .eval_function(context, arena)
            }
            Self::Function { bounds, body } => {
                context.descend(arena)?;
                let domains = bounds
                    .iter()
                    .map(|binding| Ok((binding.domain.values(context, arena)?, binding.tuple_size)))
                    .collect::<Result<_, CoreError>>()?;
                Ok(FunctionValue::Lazy(Box::new(LazyFunction {
                    domains,
                    body: Arc::new(body.as_ref().clone()),
                    snapshot: Snapshot::new(context),
                })))
            }
            _ => Ok(FunctionValue::Scalar(self.eval(context, arena)?)),
        }
    }
}

impl FunctionValue {
    pub(super) fn at(self, key: Scalar, arena: &mut Arena) -> Result<Scalar, CoreError> {
        self.select(key, arena)?.materialize(arena)
    }

    fn select(self, key: Scalar, arena: &mut Arena) -> Result<Self, CoreError> {
        match self {
            Self::Scalar(value) => Ok(Self::Scalar(arena.at(value, key)?)),
            Self::Composite(mut values) => {
                let index = values
                    .iter()
                    .position(|(candidate, _)| *candidate == key)
                    .ok_or_else(|| {
                        CoreError::protocol("Function argument is outside its domain")
                    })?;
                Ok(values.swap_remove(index).1)
            }
            Self::Lazy(function) => {
                let keys = if function.domains.len() == 1 {
                    vec![key]
                } else {
                    arena.sequence(key)?
                };
                if keys.len() != function.domains.len() {
                    return Err(CoreError::protocol(
                        "Function argument is outside its domain",
                    ));
                }
                let mut context = function.snapshot.context();
                let mut locals = context.locals.to_vec();
                for ((values, tuple_size), key) in function.domains.iter().zip(keys) {
                    let found = match values {
                        Values::Range(range) => {
                            if arena.model_membership(key)? {
                                false
                            } else {
                                range.contains(&key.integer()?)
                            }
                        }
                        Values::Items(values) => {
                            let mut found = false;
                            for candidate in values.clone() {
                                if arena.equal(candidate, key)? {
                                    found = true;
                                    break;
                                }
                            }
                            found
                        }
                    };
                    if !found {
                        return Err(CoreError::protocol(
                            "Function argument is outside its domain",
                        ));
                    }
                    context.descend(arena)?;
                    arena.tick()?;
                    arena.check_tuple(key, *tuple_size)?;
                    locals.push(key);
                }
                context.descend(arena)?;
                function.body.eval_function(
                    EvalContext {
                        locals: &locals,
                        ..context
                    },
                    arena,
                )
            }
        }
    }

    fn materialize(self, arena: &mut Arena) -> Result<Scalar, CoreError> {
        fn visit(
            function: &LazyFunction,
            position: usize,
            mut context: EvalContext<'_>,
            entries: &mut Vec<(Scalar, Scalar)>,
            arena: &mut Arena,
        ) -> Result<(), CoreError> {
            context.descend(arena)?;
            if let Some((values, tuple_size)) = function.domains.get(position) {
                let mut locals = context.locals.to_vec();
                for value in values.clone() {
                    arena.tick()?;
                    arena.check_tuple(value, *tuple_size)?;
                    locals.push(value);
                    visit(
                        function,
                        position + 1,
                        EvalContext {
                            locals: &locals,
                            ..context
                        },
                        entries,
                        arena,
                    )?;
                    locals.pop();
                }
            } else {
                let keys = &context.locals[function.snapshot.locals.len()..];
                let key = if keys.len() == 1 {
                    keys[0]
                } else {
                    arena.tuple(keys.to_vec())?
                };
                entries.push((key, function.body.eval(context, arena)?));
            }
            Ok(())
        }
        match self {
            Self::Scalar(value) => Ok(value),
            Self::Lazy(function) => {
                let mut entries = vec![];
                visit(
                    &function,
                    0,
                    function.snapshot.context(),
                    &mut entries,
                    arena,
                )?;
                arena.function(entries)
            }
            Self::Composite(values) => {
                let values = values
                    .into_iter()
                    .map(|(key, value)| Ok((key, value.materialize(arena)?)))
                    .collect::<Result<_, CoreError>>()?;
                arena.function(values)
            }
        }
    }

    pub(super) fn domain(self, arena: &mut Arena) -> Result<Scalar, CoreError> {
        fn visit(
            domains: &[(Values, Option<usize>)],
            position: usize,
            keys: &mut Vec<Scalar>,
            result: &mut Vec<Scalar>,
            arena: &mut Arena,
        ) -> Result<(), CoreError> {
            if let Some((values, _)) = domains.get(position) {
                for value in values.clone() {
                    arena.tick()?;
                    keys.push(value);
                    visit(domains, position + 1, keys, result, arena)?;
                    keys.pop();
                }
            } else {
                result.push(if keys.len() == 1 {
                    keys[0]
                } else {
                    arena.tuple(keys.clone())?
                });
            }
            Ok(())
        }
        match self {
            Self::Scalar(value) => arena.domain(value),
            Self::Composite(values) => arena.set(values.into_iter().map(|(key, _)| key).collect()),
            Self::Lazy(function) => {
                let mut keys = vec![];
                visit(&function.domains, 0, &mut vec![], &mut keys, arena)?;
                arena.set(keys)
            }
        }
    }
}

use crate::CoreError;
use crate::ir::{
    Binding, BodyKind, Branch, Definition, DefinitionBody, Domain, Expression, SafetyProgram, Step,
    TemporalFormula, validate_wire_index,
};
use std::collections::{BTreeMap, HashMap};

#[derive(Clone, Default, PartialEq, Eq)]
struct Summary {
    parameters: BTreeMap<usize, u8>,
    captures: BTreeMap<usize, u8>,
    contextual: bool,
    stateful: bool,
}

impl Summary {
    fn merge(&mut self, other: Self) {
        self.contextual |= other.contextual;
        self.stateful |= other.stateful;
        for (slot, phases) in other.parameters {
            *self.parameters.entry(slot).or_default() |= phases;
        }
        for (slot, phases) in other.captures {
            *self.captures.entry(slot).or_default() |= phases;
        }
    }
}

struct DefinitionSignature {
    kind: BodyKind,
    parameter_count: usize,
    capture_count: usize,
}

pub(crate) struct Metadata {
    definitions: Vec<DefinitionSignature>,
    summaries: Vec<[Option<Summary>; 4]>,
    variables: usize,
}

#[derive(Clone, Copy, Hash, PartialEq, Eq)]
struct Context {
    phase: u8,
    depth: usize,
    locals: usize,
    capacity: usize,
    parameters: usize,
    captures: usize,
    old: bool,
}

impl Context {
    fn root(phase: u8) -> Self {
        Self {
            phase,
            depth: 0,
            locals: 0,
            capacity: 40,
            parameters: 0,
            captures: 0,
            old: false,
        }
    }
    fn child(self) -> Self {
        Self {
            depth: self.depth + 1,
            ..self
        }
    }
    fn mode(self) -> usize {
        usize::from(self.phase)
    }
}

fn invalid(message: &str) -> CoreError {
    CoreError::protocol(message)
}

fn branch_expansion(branches: &[Branch], depth: usize) -> Result<(usize, usize), CoreError> {
    if depth > 48 {
        return Err(invalid("Safety expression nesting exceeds 48"));
    }
    let mut count = 0usize;
    let mut maximum = 0usize;
    for branch in branches {
        let mut alternatives = 1usize;
        let mut steps = branch.steps.len();
        for step in &branch.steps {
            if let Step::Frame { branches, .. } = step {
                let (inner_steps, inner_count) = branch_expansion(branches, depth + 1)?;
                steps = steps.saturating_add(inner_steps);
                alternatives = alternatives.saturating_mul(inner_count);
            }
        }
        maximum = maximum.max(steps);
        count = count.saturating_add(alternatives);
    }
    if maximum > 256 {
        return Err(invalid("Safety branch exceeds 256 steps"));
    }
    if count > 4096 {
        return Err(invalid("Safety expansion exceeds 4096 branches"));
    }
    Ok((maximum, count))
}

fn definition_order(definitions: &[Definition]) -> Result<Vec<(Vec<usize>, bool)>, CoreError> {
    let mut edges = vec![vec![]; definitions.len()];
    for (index, definition) in definitions.iter().enumerate() {
        for count in [
            definition.id,
            definition.parameter_count,
            definition.capture_count,
            definition.local_scope,
        ] {
            validate_wire_index(count)?;
        }
        if definition.id != index || definition.local_scope > 40 {
            return Err(invalid("Invalid safety definition ID or local scope"));
        }
        enum Node<'a> {
            Expression(&'a Expression, usize),
            Branch(&'a Branch, usize),
            Formula(&'a TemporalFormula, usize),
        }
        let mut pending = match &definition.body {
            DefinitionBody::Temporal(body)
                if definition.body_kind == BodyKind::Temporal && !definition.recursive =>
            {
                vec![Node::Formula(body, 0)]
            }
            DefinitionBody::Expression(body) if definition.body_kind == BodyKind::Expression => {
                vec![Node::Expression(body, 0)]
            }
            DefinitionBody::Action(branches) if definition.body_kind == BodyKind::Action => {
                branches
                    .iter()
                    .map(|branch| Node::Branch(branch, 0))
                    .collect()
            }
            _ => return Err(invalid("Invalid safety definition body kind")),
        };
        let mut call = |id: usize,
                        arguments: &[Expression],
                        captures: &[Expression],
                        kind|
         -> Result<(), CoreError> {
            validate_wire_index(id)?;
            let callee = definitions
                .get(id)
                .ok_or_else(|| invalid("Unknown safety definition ID"))?;
            if callee.body_kind != kind {
                return Err(invalid("Invalid safety call body kind"));
            }
            if arguments.len() != callee.parameter_count || captures.len() != callee.capture_count {
                return Err(invalid("Invalid safety call arity or capture count"));
            }
            edges[index].push(id);
            Ok(())
        };
        while let Some(node) = pending.pop() {
            match node {
                Node::Formula(formula, depth) => {
                    if depth > 40 {
                        return Err(invalid("Temporal formula nesting exceeds 40"));
                    }
                    match formula {
                        TemporalFormula::Call {
                            definition,
                            arguments,
                            captures,
                        } => {
                            call(*definition, arguments, captures, BodyKind::Temporal)?;
                            pending.extend(
                                arguments
                                    .iter()
                                    .chain(captures)
                                    .map(|expression| Node::Expression(expression, 0)),
                            );
                        }
                        TemporalFormula::Frame {
                            arguments,
                            captures,
                            formula,
                            ..
                        } => {
                            pending.extend(
                                arguments
                                    .iter()
                                    .chain(captures)
                                    .map(|expression| Node::Expression(expression, 0)),
                            );
                            pending.push(Node::Formula(formula, depth + 1));
                        }
                        TemporalFormula::Atom { expression } => {
                            pending.push(Node::Expression(expression, 0))
                        }
                        TemporalFormula::Not { formula }
                        | TemporalFormula::Always { formula }
                        | TemporalFormula::Eventually { formula } => {
                            pending.push(Node::Formula(formula, depth + 1))
                        }
                        TemporalFormula::And { left, right }
                        | TemporalFormula::Or { left, right } => pending.extend([
                            Node::Formula(left, depth + 1),
                            Node::Formula(right, depth + 1),
                        ]),
                        TemporalFormula::Forall { bounds, formula }
                        | TemporalFormula::Exists { bounds, formula } => {
                            for binding in bounds {
                                pending.extend(
                                    binding
                                        .domain
                                        .children()
                                        .into_iter()
                                        .map(|expression| Node::Expression(expression, 0)),
                                );
                            }
                            pending.push(Node::Formula(formula, depth + 1));
                        }
                    }
                }
                Node::Expression(expression, depth) => {
                    if depth > 48 {
                        return Err(invalid("Safety expression nesting exceeds 48"));
                    }
                    if let Expression::Call {
                        definition,
                        arguments,
                        captures,
                    } = expression
                    {
                        call(*definition, arguments, captures, BodyKind::Expression)?;
                    }
                    if let Expression::Enabled {
                        branches,
                        subscript,
                    } = expression
                    {
                        pending.extend(
                            branches
                                .iter()
                                .map(|branch| Node::Branch(branch, depth + 1)),
                        );
                        pending.extend(
                            subscript
                                .iter()
                                .map(|body| Node::Expression(body, depth + 1)),
                        );
                    } else {
                        pending.extend(
                            expression
                                .children()
                                .into_iter()
                                .map(|body| Node::Expression(body, depth + 1)),
                        );
                    }
                }
                Node::Branch(branch, depth) => {
                    if depth > 48 {
                        return Err(invalid("Safety expression nesting exceeds 48"));
                    }
                    for step in &branch.steps {
                        match step {
                            Step::Call {
                                definition,
                                arguments,
                                captures,
                            } => {
                                call(*definition, arguments, captures, BodyKind::Action)?;
                                pending.extend(
                                    arguments
                                        .iter()
                                        .chain(captures)
                                        .map(|body| Node::Expression(body, depth + 1)),
                                );
                            }
                            Step::Frame {
                                arguments,
                                captures,
                                branches,
                                ..
                            } => {
                                pending.extend(
                                    arguments
                                        .iter()
                                        .chain(captures)
                                        .map(|body| Node::Expression(body, depth + 1)),
                                );
                                pending.extend(
                                    branches
                                        .iter()
                                        .map(|branch| Node::Branch(branch, depth + 1)),
                                );
                            }
                            Step::Guard { expression }
                            | Step::Assign {
                                value: expression, ..
                            } => pending.push(Node::Expression(expression, depth + 1)),
                            Step::Bind { domain, .. } | Step::Choose { domain, .. } => pending
                                .extend(
                                    domain
                                        .children()
                                        .into_iter()
                                        .map(|body| Node::Expression(body, depth + 1)),
                                ),
                        }
                    }
                }
            }
        }
    }

    let mut colors = vec![0_u8; definitions.len()];
    let mut order = vec![];
    for root in 0..definitions.len() {
        if colors[root] != 0 {
            continue;
        }
        colors[root] = 1;
        let mut pending = vec![(root, 0)];
        while let Some((definition, edge)) = pending.last_mut() {
            if let Some(&callee) = edges[*definition].get(*edge) {
                *edge += 1;
                match colors[callee] {
                    0 => {
                        colors[callee] = 1;
                        pending.push((callee, 0));
                    }
                    1 => {}
                    _ => {}
                }
            } else {
                colors[*definition] = 2;
                order.push(*definition);
                pending.pop();
            }
        }
    }
    let mut reverse = vec![vec![]; definitions.len()];
    for (caller, callees) in edges.iter().enumerate() {
        for callee in callees {
            reverse[*callee].push(caller);
        }
    }
    let mut assigned = vec![false; definitions.len()];
    let mut components = vec![];
    for root in order.into_iter().rev() {
        if assigned[root] {
            continue;
        }
        assigned[root] = true;
        let mut ids = vec![];
        let mut pending = vec![root];
        while let Some(id) = pending.pop() {
            ids.push(id);
            for caller in &reverse[id] {
                if !assigned[*caller] {
                    assigned[*caller] = true;
                    pending.push(*caller);
                }
            }
        }
        let recursive = ids.len() > 1 || edges[ids[0]].contains(&ids[0]);
        if recursive && ids.iter().any(|id| !definitions[*id].recursive) {
            return Err(invalid("Recursive safety definition graph"));
        }
        components.push((ids, recursive));
    }
    components.reverse();
    Ok(components)
}

type CachedAnalysis = Result<Summary, (&'static str, String)>;

struct Analyzer<'metadata> {
    metadata: &'metadata Metadata,
    cache: HashMap<(usize, Context), CachedAnalysis>,
}

impl<'metadata> Analyzer<'metadata> {
    fn new(metadata: &'metadata Metadata) -> Self {
        Self {
            metadata,
            cache: HashMap::new(),
        }
    }
}

impl Analyzer<'_> {
    fn domain(&mut self, domain: &Domain, context: Context) -> Result<Summary, CoreError> {
        let mut summary = Summary::default();
        for child in domain.children() {
            summary.merge(self.expression(child, context)?);
        }
        Ok(summary)
    }

    fn bindings(
        &mut self,
        bounds: &[Binding],
        context: Context,
    ) -> Result<(Summary, Context), CoreError> {
        if bounds.is_empty()
            || bounds.len() > 40
            || context.locals + bounds.len() > context.capacity
        {
            return Err(invalid("Invalid safety binding count"));
        }
        let mut child = context;
        let mut summary = Summary::default();
        for bound in bounds {
            validate_wire_index(bound.slot)?;
            if let Some(size) = bound.tuple_size {
                validate_wire_index(size)?;
            }
            if bound.slot != child.locals || bound.tuple_size.is_some_and(|size| size > 256) {
                return Err(invalid("Invalid bound variable slot"));
            }
            summary.merge(self.domain(&bound.domain, child)?);
            child.locals += 1;
        }
        Ok((summary, child))
    }

    fn branches(&mut self, branches: &[Branch], context: Context) -> Result<Summary, CoreError> {
        branch_expansion(branches, context.depth)?;
        let mut summary = Summary::default();
        for branch in branches {
            if branch.steps.len() > 256 {
                return Err(invalid("Safety branch exceeds 256 steps"));
            }
            let mut context = context;
            for step in &branch.steps {
                match step {
                    Step::Bind {
                        slot, tuple_size, ..
                    } => {
                        validate_wire_index(*slot)?;
                        if let Some(size) = tuple_size {
                            validate_wire_index(*size)?;
                        }
                    }
                    Step::Assign { slot, .. } | Step::Choose { slot, .. } => {
                        validate_wire_index(*slot)?
                    }
                    _ => {}
                }
                match step {
                    Step::Frame {
                        arguments,
                        captures,
                        parameter_count,
                        capture_count,
                        local_scope,
                        branches,
                    } => {
                        let child = self.frame_context(
                            *parameter_count,
                            *capture_count,
                            *local_scope,
                            context,
                        )?;
                        let required = self.branches(branches, child)?;
                        summary.merge(self.actuals(
                            arguments,
                            captures,
                            *parameter_count,
                            *capture_count,
                            required,
                            context,
                        )?);
                    }
                    Step::Call {
                        definition,
                        arguments,
                        captures,
                    } => {
                        summary.merge(self.call(
                            *definition,
                            arguments,
                            captures,
                            BodyKind::Action,
                            context,
                        )?);
                    }
                    Step::Guard { expression } => {
                        summary.merge(self.expression(expression, context)?)
                    }
                    Step::Assign { slot, value } => {
                        if *slot >= self.metadata.variables {
                            return Err(invalid("Invalid safety assignment slot"));
                        }
                        summary.merge(self.expression(value, context)?);
                    }
                    Step::Choose { slot, domain } => {
                        if *slot >= self.metadata.variables {
                            return Err(invalid("Invalid safety assignment slot"));
                        }
                        summary.merge(self.domain(domain, context)?);
                    }
                    Step::Bind {
                        slot,
                        domain,
                        tuple_size,
                    } => {
                        if *slot != context.locals
                            || context.locals >= context.capacity
                            || tuple_size.is_some_and(|size| size > 256)
                        {
                            return Err(invalid("Invalid bound variable slot"));
                        }
                        summary.merge(self.domain(domain, context)?);
                        context.locals += 1;
                    }
                }
            }
        }
        Ok(summary)
    }

    fn frame_context(
        &self,
        parameters: usize,
        captures: usize,
        capacity: usize,
        context: Context,
    ) -> Result<Context, CoreError> {
        for count in [parameters, captures, capacity] {
            validate_wire_index(count)?;
        }
        if capacity > 40 {
            return Err(invalid("Invalid safety frame local scope"));
        }
        Ok(Context {
            parameters,
            captures,
            capacity,
            locals: 0,
            old: false,
            ..context.child()
        })
    }

    fn actuals(
        &mut self,
        arguments: &[Expression],
        captures: &[Expression],
        parameters: usize,
        capture_count: usize,
        required: Summary,
        context: Context,
    ) -> Result<Summary, CoreError> {
        if arguments.len() != parameters || captures.len() != capture_count {
            return Err(invalid("Invalid safety frame arity or capture count"));
        }
        let mut summary = Summary {
            contextual: required.contextual,
            stateful: required.stateful,
            ..Summary::default()
        };
        for (actuals, uses) in [
            (arguments, &required.parameters),
            (captures, &required.captures),
        ] {
            for (slot, actual) in actuals.iter().enumerate() {
                let phases = uses.get(&slot).copied().unwrap_or_default();
                if phases == 0 {
                    self.expression(actual, context.child())?;
                }
                for phase in 0..4 {
                    if phases & (1 << phase) != 0 {
                        summary.merge(self.expression(
                            actual,
                            Context {
                                phase,
                                ..context.child()
                            },
                        )?);
                    }
                }
            }
        }
        Ok(summary)
    }

    fn call(
        &mut self,
        definition: usize,
        arguments: &[Expression],
        captures: &[Expression],
        kind: BodyKind,
        context: Context,
    ) -> Result<Summary, CoreError> {
        validate_wire_index(definition)?;
        let callee = self
            .metadata
            .definitions
            .get(definition)
            .ok_or_else(|| invalid("Unknown safety definition ID"))?;
        if callee.kind != kind {
            return Err(invalid("Invalid safety call body kind"));
        }
        if arguments.len() != callee.parameter_count || captures.len() != callee.capture_count {
            return Err(invalid("Invalid safety call arity or capture count"));
        }
        let required = self.metadata.summaries[definition][context.mode()]
            .clone()
            .ok_or_else(|| invalid("Invalid safety call phase"))?;
        self.actuals(
            arguments,
            captures,
            callee.parameter_count,
            callee.capture_count,
            required,
            context,
        )
    }

    fn expression(
        &mut self,
        expression: &Expression,
        context: Context,
    ) -> Result<Summary, CoreError> {
        let key = (std::ptr::from_ref(expression) as usize, context);
        if let Some(result) = self.cache.get(&key) {
            return result
                .clone()
                .map_err(|(code, message)| CoreError { code, message });
        }
        let result = self.expression_uncached(expression, context);
        self.cache.insert(
            key,
            result
                .as_ref()
                .cloned()
                .map_err(|error| (error.code, error.message.clone())),
        );
        result
    }

    fn expression_uncached(
        &mut self,
        expression: &Expression,
        context: Context,
    ) -> Result<Summary, CoreError> {
        if context.depth > 48 {
            return Err(invalid("Safety expression nesting exceeds 48"));
        }
        match expression {
            Expression::Call { definition, .. } => validate_wire_index(*definition)?,
            Expression::Parameter { slot }
            | Expression::Capture { slot }
            | Expression::Bound { slot }
            | Expression::Read { slot, .. } => validate_wire_index(*slot)?,
            Expression::Fold { accumulator, .. } => validate_wire_index(*accumulator)?,
            _ => {}
        }
        let mut summary = Summary::default();
        match expression {
            Expression::Frame {
                arguments,
                captures,
                parameter_count,
                capture_count,
                local_scope,
                body,
            } => {
                let child =
                    self.frame_context(*parameter_count, *capture_count, *local_scope, context)?;
                let required = self.expression(body, child)?;
                return self.actuals(
                    arguments,
                    captures,
                    *parameter_count,
                    *capture_count,
                    required,
                    context,
                );
            }
            Expression::Call {
                definition,
                arguments,
                captures,
            } => {
                return self.call(
                    *definition,
                    arguments,
                    captures,
                    BodyKind::Expression,
                    context,
                );
            }
            Expression::Parameter { slot } => {
                if *slot >= context.parameters {
                    return Err(invalid("Invalid safety parameter reference"));
                }
                summary.parameters.insert(*slot, 1 << context.phase);
                return Ok(summary);
            }
            Expression::Capture { slot } => {
                if *slot >= context.captures {
                    return Err(invalid("Invalid safety capture reference"));
                }
                summary.captures.insert(*slot, 1 << context.phase);
                return Ok(summary);
            }
            Expression::Prime { argument } => {
                if context.phase != 1 {
                    return Err(invalid("Prime requires an action context"));
                }
                summary.merge(self.expression(
                    argument,
                    Context {
                        phase: 2,
                        ..context.child()
                    },
                )?);
                summary.contextual = true;
                return Ok(summary);
            }
            Expression::Read { slot, next } => {
                if *slot >= self.metadata.variables
                    || (context.phase == 0 && !*next)
                    || (context.phase == 2 && *next)
                    || context.phase == 3
                {
                    return Err(invalid("Invalid safety variable read"));
                }
                summary.contextual = true;
                summary.stateful = true;
            }
            Expression::Bound { slot } => {
                if *slot >= context.locals {
                    return Err(invalid("Unbound quantified variable"));
                }
                summary.contextual = true;
            }
            Expression::Old => {
                if !context.old {
                    return Err(invalid("Unbound EXCEPT @"));
                }
                summary.contextual = true;
            }
            Expression::UnmatchedCase { location } => {
                if location.is_empty() {
                    return Err(invalid("Invalid unmatched CASE location"));
                }
                summary.stateful = true;
                summary.contextual = true;
            }
            Expression::Choose { binding, body } => {
                let (binding_summary, child) =
                    self.bindings(std::slice::from_ref(binding), context.child())?;
                summary.merge(binding_summary);
                summary.merge(self.expression(body, child)?);
                return Ok(summary);
            }
            Expression::Forall { bounds, body }
            | Expression::Exists { bounds, body }
            | Expression::Function { bounds, body }
            | Expression::Filter { bounds, body }
            | Expression::MapSet { bounds, body } => {
                let (binding_summary, child) = self.bindings(bounds, context.child())?;
                summary.merge(binding_summary);
                summary.merge(self.expression(body, child)?);
                return Ok(summary);
            }
            Expression::Fold {
                accumulator,
                initial,
                collection,
                body,
                ..
            } => {
                if *accumulator != context.locals || context.locals + 2 > context.capacity {
                    return Err(invalid("Invalid fold variable slot"));
                }
                summary.merge(self.expression(initial, context.child())?);
                summary.merge(self.expression(collection, context.child())?);
                summary.merge(self.expression(
                    body,
                    Context {
                        locals: context.locals + 2,
                        ..context.child()
                    },
                )?);
                return Ok(summary);
            }
            Expression::SelectSeq {
                slot,
                sequence,
                body,
            }
            | Expression::SortSeq {
                slot,
                sequence,
                body,
            } => {
                validate_wire_index(*slot)?;
                let arity = if matches!(expression, Expression::SortSeq { .. }) {
                    2
                } else {
                    1
                };
                if *slot != context.locals || context.locals + arity > context.capacity {
                    return Err(invalid("Invalid sequence callback variable slot"));
                }
                summary.merge(self.expression(sequence, context.child())?);
                summary.merge(self.expression(
                    body,
                    Context {
                        locals: context.locals + arity,
                        ..context.child()
                    },
                )?);
                return Ok(summary);
            }
            Expression::Update { target, updates } => {
                summary.merge(self.expression(target, context.child())?);
                for update in updates {
                    if update.path.is_empty() || update.path.len() > 48 {
                        return Err(invalid("Empty EXCEPT path"));
                    }
                    for part in &update.path {
                        summary.merge(self.expression(part, context.child())?);
                    }
                    summary.merge(self.expression(
                        &update.value,
                        Context {
                            old: true,
                            ..context.child()
                        },
                    )?);
                }
                return Ok(summary);
            }
            Expression::Enabled {
                branches,
                subscript,
            } => {
                if context.phase == 3 {
                    return Err(invalid("ENABLED is not a constant"));
                }
                summary.merge(self.branches(
                    branches,
                    Context {
                        phase: 1,
                        ..context.child()
                    },
                )?);
                if let Some(subscript) = subscript {
                    summary.merge(self.expression(
                        subscript,
                        Context {
                            phase: 2,
                            ..context.child()
                        },
                    )?);
                }
                summary.stateful = true;
                summary.contextual = true;
                return Ok(summary);
            }
            _ => {}
        }
        for child in expression.children() {
            summary.merge(self.expression(child, context.child())?);
        }
        Ok(summary)
    }

    fn formula(
        &mut self,
        formula: &TemporalFormula,
        depth: usize,
        context: Context,
    ) -> Result<Summary, CoreError> {
        if depth > 40 {
            return Err(invalid("Temporal formula nesting exceeds 40"));
        }
        let mut summary = Summary::default();
        match formula {
            TemporalFormula::Call {
                definition,
                arguments,
                captures,
            } => {
                return self.call(
                    *definition,
                    arguments,
                    captures,
                    BodyKind::Temporal,
                    context,
                );
            }
            TemporalFormula::Frame {
                arguments,
                captures,
                parameter_count,
                capture_count,
                local_scope,
                formula,
            } => {
                let child =
                    self.frame_context(*parameter_count, *capture_count, *local_scope, context)?;
                let required = self.formula(formula, depth + 1, child)?;
                return self.actuals(
                    arguments,
                    captures,
                    *parameter_count,
                    *capture_count,
                    required,
                    context,
                );
            }
            TemporalFormula::Atom { expression } => {
                summary.merge(self.expression(expression, context)?);
            }
            TemporalFormula::Not { formula }
            | TemporalFormula::Always { formula }
            | TemporalFormula::Eventually { formula } => {
                summary.merge(self.formula(formula, depth + 1, context)?);
            }
            TemporalFormula::And { left, right } | TemporalFormula::Or { left, right } => {
                summary.merge(self.formula(left, depth + 1, context)?);
                summary.merge(self.formula(right, depth + 1, context)?);
            }
            TemporalFormula::Forall { bounds, formula }
            | TemporalFormula::Exists { bounds, formula } => {
                if bounds.is_empty() || context.locals + bounds.len() > context.capacity {
                    return Err(invalid("Invalid temporal binding count"));
                }
                for (index, bound) in bounds.iter().enumerate() {
                    if bound.slot != context.locals + index
                        || bound.tuple_size.is_some_and(|size| size > 256)
                    {
                        return Err(invalid("Invalid temporal binding slot"));
                    }
                    summary.merge(self.domain(
                        &bound.domain,
                        Context {
                            phase: 3,
                            ..context
                        },
                    )?);
                }
                summary.merge(self.formula(
                    formula,
                    depth + 1,
                    Context {
                        locals: context.locals + bounds.len(),
                        ..context
                    },
                )?);
            }
        }
        Ok(summary)
    }
}

impl Metadata {
    fn expression(&self, expression: &Expression, context: Context) -> Result<Summary, CoreError> {
        Analyzer::new(self).expression(expression, context)
    }

    fn branches(&self, branches: &[Branch], context: Context) -> Result<Summary, CoreError> {
        Analyzer::new(self).branches(branches, context)
    }

    fn formula(
        &self,
        formula: &TemporalFormula,
        depth: usize,
        context: Context,
    ) -> Result<Summary, CoreError> {
        Analyzer::new(self).formula(formula, depth, context)
    }

    pub(crate) fn is_constant(&self, expression: &Expression) -> bool {
        self.expression(expression, Context::root(1))
            .is_ok_and(|summary| {
                !summary.stateful && summary.parameters.is_empty() && summary.captures.is_empty()
            })
    }

    pub(crate) fn is_context_free(&self, expression: &Expression) -> bool {
        self.expression(expression, Context::root(1))
            .is_ok_and(|summary| {
                !summary.contextual && summary.parameters.is_empty() && summary.captures.is_empty()
            })
    }
}

pub(crate) fn validate_program(program: &SafetyProgram) -> Result<Metadata, CoreError> {
    validate_wire_index(program.variables.len())?;
    let definitions = program
        .definitions
        .as_deref()
        .ok_or_else(|| invalid("Missing safety IR v2 definitions"))?;
    validate_wire_index(definitions.len())?;
    let order = definition_order(definitions)?;
    let mut metadata = Metadata {
        definitions: definitions
            .iter()
            .map(|definition| DefinitionSignature {
                kind: definition.body_kind,
                parameter_count: definition.parameter_count,
                capture_count: definition.capture_count,
            })
            .collect(),
        summaries: (0..definitions.len())
            .map(|_| std::array::from_fn(|_| None))
            .collect(),
        variables: program.variables.len(),
    };
    for (ids, recursive) in order {
        if recursive {
            for id in &ids {
                metadata.summaries[*id] = std::array::from_fn(|_| Some(Summary::default()));
            }
        }
        let mut errors = HashMap::new();
        loop {
            let mut changed = false;
            for id in &ids {
                let definition = &definitions[*id];
                let mut summaries = std::array::from_fn(|_| None);
                for (phase, target) in summaries.iter_mut().enumerate() {
                    if recursive && metadata.summaries[*id][phase].is_none() {
                        continue;
                    }
                    let context = Context {
                        parameters: definition.parameter_count,
                        captures: definition.capture_count,
                        capacity: definition.local_scope,
                        ..Context::root(phase as u8)
                    };
                    let result = match &definition.body {
                        DefinitionBody::Temporal(formula) if phase == 1 => {
                            metadata.formula(formula, 0, context)
                        }
                        DefinitionBody::Temporal(_) => {
                            Err(invalid("Invalid safety temporal definition phase"))
                        }
                        DefinitionBody::Expression(body) => metadata.expression(body, context),
                        DefinitionBody::Action(branches) if phase <= 1 => {
                            metadata.branches(branches, context).map(|mut summary| {
                                summary.stateful = true;
                                summary
                            })
                        }
                        DefinitionBody::Action(_) => {
                            Err(invalid("Invalid safety action definition phase"))
                        }
                    };
                    match result {
                        Ok(summary) => *target = Some(summary),
                        Err(error) => {
                            errors.entry(*id).or_insert(error);
                        }
                    }
                }
                changed |= metadata.summaries[*id] != summaries;
                metadata.summaries[*id] = summaries;
            }
            if !recursive || !changed {
                break;
            }
        }
        for id in ids {
            if metadata.summaries[id].iter().all(Option::is_none) {
                return Err(errors
                    .remove(&id)
                    .unwrap_or_else(|| invalid("Invalid safety definition")));
            }
        }
    }
    metadata.branches(&program.initial, Context::root(0))?;
    metadata.branches(&program.next, Context::root(1))?;
    for (predicates, phase) in [
        (&program.invariants, 2),
        (&program.initial_properties, 2),
        (&program.constraints, 2),
        (&program.action_properties, 1),
        (&program.action_constraints, 1),
        (&program.assumptions, 3),
    ] {
        for predicate in predicates {
            metadata.expression(&predicate.expression, Context::root(phase))?;
        }
    }
    for formula in program
        .properties
        .iter()
        .map(|property| &property.formula)
        .chain(&program.fairness)
    {
        metadata.formula(formula, 0, Context::root(1))?;
    }
    Ok(metadata)
}

fn eval_reference<T>(
    &self,
    ctx: EvalContext<'_>,
    arena: &mut Arena,
    evaluate: fn(&Expression, EvalContext<'_>, &mut Arena) -> Result<T, CoreError>,
) -> Result<T, CoreError> {
    match self {
        Self::Frame {
            arguments,
            captures,
            body,
            ..
        } => {
            arena.consume(1)?;
            let frame = CallFrame::new(arguments, captures, ctx);
            evaluate(
                body,
                EvalContext {
                    locals: &[],
                    frame: Some(&frame),
                    old: None,
                    ..ctx
                },
                arena,
            )
        }
        Self::Call {
            definition,
            arguments,
            captures,
        } => {
            arena.consume(1)?;
            let definition = arena
                .definitions
                .get(*definition)
                .ok_or_else(|| CoreError::protocol("Unknown safety definition"))?;
            let frame = CallFrame::new(arguments, captures, ctx);
            let DefinitionBody::Expression(body) = &definition.body else {
                return Err(CoreError::protocol("Invalid safety call body kind"));
            };
            evaluate(
                body,
                EvalContext {
                    recursive: ctx.recursive || definition.recursive,
                    locals: &[],
                    frame: Some(&frame),
                    old: None,
                    ..ctx
                },
                arena,
            )
        }
        Self::Parameter { slot } | Self::Capture { slot } => {
            let frame = ctx
                .frame
                .ok_or_else(|| CoreError::protocol("Missing lexical call frame"))?;
            let bindings = if matches!(self, Self::Parameter { .. }) {
                &frame.arguments
            } else {
                &frame.captures
            };
            bindings
                .get(*slot)
                .ok_or_else(|| CoreError::protocol("Invalid lexical reference"))?
                .evaluate(ctx, arena, evaluate)
        }
        _ => Err(CoreError::protocol("Expected a lexical reference")),
    }
}

pub(crate) fn visit_branch(
    branch: &Branch,
    position: usize,
    ctx: EvalContext<'_>,
    next: &mut [Option<Scalar>],
    arena: &mut Arena,
    visitor: &mut BranchVisitor<'_>,
) -> Result<bool, CoreError> {
    let mut ctx = ctx;
    ctx.descend(arena)?;
    arena.tick()?;
    let Some(step) = branch.steps.get(position) else {
        return visitor(next, arena);
    };
    let context = EvalContext { next, ..ctx };
    match step {
        Step::Call {
            definition,
            arguments,
            captures,
        } => {
            arena.consume(1)?;
            let definition = arena
                .definitions
                .get(*definition)
                .ok_or_else(|| CoreError::protocol("Unknown safety definition"))?;
            let DefinitionBody::Action(branches) = &definition.body else {
                return Err(CoreError::protocol("Invalid safety call body kind"));
            };
            let frame = CallFrame::new(arguments, captures, context);
            let inner = EvalContext {
                recursive: ctx.recursive || definition.recursive,
                locals: &[],
                frame: Some(&frame),
                old: None,
                ..ctx
            };
            for inner_branch in branches {
                if visit_branch(inner_branch, 0, inner, next, arena, &mut |next, arena| {
                    visit_branch(branch, position + 1, ctx, next, arena, visitor)
                })? {
                    return Ok(true);
                }
            }
            Ok(false)
        }
        Step::Frame {
            arguments,
            captures,
            branches,
            ..
        } => {
            arena.consume(1)?;
            let frame = CallFrame::new(arguments, captures, context);
            let inner = EvalContext {
                locals: &[],
                frame: Some(&frame),
                old: None,
                ..ctx
            };
            for inner_branch in branches {
                if visit_branch(inner_branch, 0, inner, next, arena, &mut |next, arena| {
                    visit_branch(branch, position + 1, ctx, next, arena, visitor)
                })? {
                    return Ok(true);
                }
            }
            Ok(false)
        }
        Step::Guard { expression } => {
            if expression.eval(context, arena)?.boolean()? {
                visit_branch(branch, position + 1, ctx, next, arena, visitor)
            } else {
                Ok(false)
            }
        }
        Step::Assign { slot, value } => {
            let value = value.eval(context, arena)?;
            let previous = next[*slot];
            if let Some(previous) = previous
                && !arena.equal(previous, value)?
            {
                return Ok(false);
            }
            next[*slot] = Some(value);
            let result = visit_branch(branch, position + 1, ctx, next, arena, visitor);
            next[*slot] = previous;
            result
        }
        Step::Choose { slot, domain } => {
            if let Some(value) = next[*slot] {
                return if domain.contains(value, context, arena)? {
                    visit_branch(branch, position + 1, ctx, next, arena, visitor)
                } else {
                    Ok(false)
                };
            }
            for value in domain.values(context, arena)? {
                next[*slot] = Some(value);
                let found = visit_branch(branch, position + 1, ctx, next, arena, visitor)?;
                next[*slot] = None;
                if found {
                    return Ok(true);
                }
            }
            Ok(false)
        }
        Step::Bind {
            slot,
            domain,
            tuple_size,
        } => {
            let values = domain.values(context, arena)?;
            let mut locals = ctx.locals.to_vec();
            if *slot != locals.len() {
                return Err(CoreError::protocol("Unbound action variable"));
            }
            for value in values {
                arena.check_tuple(value, *tuple_size)?;
                locals.push(value);
                let found = visit_branch(
                    branch,
                    position + 1,
                    EvalContext {
                        locals: &locals,
                        ..ctx
                    },
                    next,
                    arena,
                    visitor,
                )?;
                locals.pop();
                if found {
                    return Ok(true);
                }
            }
            Ok(false)
        }
    }
}

    fn evaluate<T>(
        &self,
        context: EvalContext<'_>,
        arena: &mut Arena,
        evaluate: fn(&Expression, EvalContext<'_>, &mut Arena) -> Result<T, CoreError>,
    ) -> Result<T, CoreError> {
        arena.consume(1)?;
        evaluate(
            &self.expression,
            EvalContext {
                locals: &self.locals,
                frame: self.frame.as_deref(),
                old: self.old,
                ..context
            },
            arena,
        )
    }
}
impl CallFrame {
    pub(crate) fn new(
        arguments: &[Expression],
        captures: &[Expression],
        context: EvalContext<'_>,
    ) -> Self {
        let parent = context
            .frame
            .filter(|_| !arguments.is_empty() || !captures.is_empty())
            .cloned()
            .map(Arc::new);
        Self {
            arguments: arguments
                .iter()
                .map(|value| Argument::new(value, context, parent.clone()))
                .collect(),
            captures: captures
                .iter()
                .map(|value| Argument::new(value, context, parent.clone()))
                .collect(),
        }
    }
}

use crate::Value;
use crate::ir::{Binding, Branch, Domain, Expression, Step, TemporalFormula, Update};
use std::mem;

const DEPTH_BUDGET: usize = 32;

enum Detached {
    Expression(Expression),
    Branch(Branch),
    Formula(TemporalFormula),
    Value(Value),
}

type Worklist = Vec<Detached>;

#[inline(always)]
fn is_leaf_value(value: &Value) -> bool {
    match value {
        Value::Null
        | Value::Bool(_)
        | Value::Int(_)
        | Value::String(_)
        | Value::Bytes(_)
        | Value::ModelValue(_) => true,
        Value::List(items) | Value::Set(items) => items.is_empty(),
        Value::Record(fields) => fields.is_empty(),
        Value::Map(entries) => entries.is_empty(),
    }
}

#[inline(always)]
fn is_flat_value(value: &Value) -> bool {
    match value {
        Value::Null
        | Value::Bool(_)
        | Value::Int(_)
        | Value::String(_)
        | Value::Bytes(_)
        | Value::ModelValue(_) => true,
        Value::List(items) | Value::Set(items) => items.iter().all(is_leaf_value),
        Value::Record(fields) => fields.iter().all(|(_, item)| is_leaf_value(item)),
        Value::Map(entries) => entries
            .iter()
            .all(|(key, item)| is_leaf_value(key) && is_leaf_value(item)),
    }
}

#[inline(always)]
fn is_shallow_value(value: &Value) -> bool {
    match value {
        Value::Null
        | Value::Bool(_)
        | Value::Int(_)
        | Value::String(_)
        | Value::Bytes(_)
        | Value::ModelValue(_) => true,
        Value::List(items) | Value::Set(items) => items.iter().all(is_flat_value),
        Value::Record(fields) => fields.iter().all(|(_, item)| is_flat_value(item)),
        Value::Map(entries) => entries
            .iter()
            .all(|(key, item)| is_flat_value(key) && is_flat_value(item)),
    }
}

fn is_leaf_expression(expression: &Expression) -> bool {
    match expression {
        Expression::Parameter { .. }
        | Expression::Capture { .. }
        | Expression::Bound { .. }
        | Expression::Old
        | Expression::UnmatchedCase { .. }
        | Expression::Literal { .. }
        | Expression::Read { .. } => true,
        Expression::Data { value } => is_leaf_value(value),
        _ => false,
    }
}

fn is_leaf_branch(branch: &Branch) -> bool {
    branch.steps.is_empty()
}

fn is_leaf_formula(formula: &TemporalFormula) -> bool {
    matches!(
        formula,
        TemporalFormula::Atom { expression } if is_leaf_expression(expression)
    )
}

#[inline(always)]
fn dispose_value(mut value: Value, budget: usize, worklist: &mut Worklist) {
    if is_flat_value(&value) {
        return;
    }
    if budget == 0 {
        worklist.push(Detached::Value(value));
        return;
    }
    descend_value(&mut value, budget - 1, worklist);
}

#[inline(never)]
fn descend_value(value: &mut Value, budget: usize, worklist: &mut Worklist) {
    detach_value(value, budget, worklist);
}

fn dispose_expression(mut expression: Expression, budget: usize, worklist: &mut Worklist) {
    if is_leaf_expression(&expression) {
        return;
    }
    if budget == 0 {
        worklist.push(Detached::Expression(expression));
        return;
    }
    detach_expression(&mut expression, budget - 1, worklist);
}

fn dispose_branch(mut branch: Branch, budget: usize, worklist: &mut Worklist) {
    if is_leaf_branch(&branch) {
        return;
    }
    if budget == 0 {
        worklist.push(Detached::Branch(branch));
        return;
    }
    detach_branch(&mut branch, budget - 1, worklist);
}

fn dispose_formula(mut formula: TemporalFormula, budget: usize, worklist: &mut Worklist) {
    if is_leaf_formula(&formula) {
        return;
    }
    if budget == 0 {
        worklist.push(Detached::Formula(formula));
        return;
    }
    detach_formula(&mut formula, budget - 1, worklist);
}

fn dispose_expressions(expressions: Vec<Expression>, budget: usize, worklist: &mut Worklist) {
    for expression in expressions {
        dispose_expression(expression, budget, worklist);
    }
}

fn dispose_fields(fields: Vec<(String, Expression)>, budget: usize, worklist: &mut Worklist) {
    for (_, expression) in fields {
        dispose_expression(expression, budget, worklist);
    }
}

fn dispose_branches(branches: Vec<Branch>, budget: usize, worklist: &mut Worklist) {
    for branch in branches {
        dispose_branch(branch, budget, worklist);
    }
}

fn dispose_update(update: Update, budget: usize, worklist: &mut Worklist) {
    dispose_expressions(update.path, budget, worklist);
    dispose_expression(update.value, budget, worklist);
}

fn detach_boxed(child: &mut Expression, budget: usize, worklist: &mut Worklist) {
    if !is_leaf_expression(child) {
        dispose_expression(mem::replace(child, Expression::Old), budget, worklist);
    }
}

fn detach_boxed_formula(child: &mut TemporalFormula, budget: usize, worklist: &mut Worklist) {
    if !is_leaf_formula(child) {
        dispose_formula(
            mem::replace(
                child,
                TemporalFormula::Atom {
                    expression: Expression::Old,
                },
            ),
            budget,
            worklist,
        );
    }
}

fn detach_domain(domain: &mut Domain, budget: usize, worklist: &mut Worklist) {
    match domain {
        Domain::Value { value } => detach_boxed(value, budget, worklist),
        Domain::Range { lower, upper } => {
            detach_boxed(lower, budget, worklist);
            detach_boxed(upper, budget, worklist);
        }
        Domain::Set { values } => dispose_expressions(mem::take(values), budget, worklist),
    }
}

fn detach_bindings(bounds: &mut Vec<Binding>, budget: usize, worklist: &mut Worklist) {
    for mut binding in mem::take(bounds) {
        detach_domain(&mut binding.domain, budget, worklist);
    }
}

fn detach_step(step: &mut Step, budget: usize, worklist: &mut Worklist) {
    match step {
        Step::Call {
            arguments,
            captures,
            ..
        } => {
            dispose_expressions(mem::take(arguments), budget, worklist);
            dispose_expressions(mem::take(captures), budget, worklist);
        }
        Step::Frame {
            arguments,
            captures,
            branches,
            ..
        } => {
            dispose_expressions(mem::take(arguments), budget, worklist);
            dispose_expressions(mem::take(captures), budget, worklist);
            dispose_branches(mem::take(branches), budget, worklist);
        }
        Step::Bind { domain, .. } | Step::Choose { domain, .. } => {
            detach_domain(domain, budget, worklist)
        }
        Step::Guard { expression }
        | Step::Assign {
            value: expression, ..
        } => detach_boxed(expression, budget, worklist),
    }
}

fn detach_branch(branch: &mut Branch, budget: usize, worklist: &mut Worklist) {
    for mut step in mem::take(&mut branch.steps) {
        detach_step(&mut step, budget, worklist);
    }
}

fn detach_value(value: &mut Value, budget: usize, worklist: &mut Worklist) {
    match value {
        Value::Null
        | Value::Bool(_)
        | Value::Int(_)
        | Value::String(_)
        | Value::Bytes(_)
        | Value::ModelValue(_) => {}
        Value::List(items) | Value::Set(items) => {
            for item in mem::take(items) {
                dispose_value(item, budget, worklist);
            }
        }
        Value::Record(fields) => {
            for (_, item) in mem::take(fields) {
                dispose_value(item, budget, worklist);
            }
        }
        Value::Map(entries) => {
            for (key, item) in mem::take(entries) {
                dispose_value(key, budget, worklist);
                dispose_value(item, budget, worklist);
            }
        }
    }
}

fn detach_expression(node: &mut Expression, budget: usize, worklist: &mut Worklist) {
    match node {
        Expression::Parameter { .. }
        | Expression::Capture { .. }
        | Expression::Bound { .. }
        | Expression::Old
        | Expression::UnmatchedCase { .. }
        | Expression::Literal { .. }
        | Expression::Read { .. } => {}
        Expression::Data { value } => {
            if !is_leaf_value(value) {
                dispose_value(mem::replace(value, Value::Null), budget, worklist);
            }
        }
        Expression::Frame {
            arguments,
            captures,
            body,
            ..
        } => {
            dispose_expressions(mem::take(arguments), budget, worklist);
            dispose_expressions(mem::take(captures), budget, worklist);
            detach_boxed(body, budget, worklist);
        }
        Expression::Call {
            arguments,
            captures,
            ..
        } => {
            dispose_expressions(mem::take(arguments), budget, worklist);
            dispose_expressions(mem::take(captures), budget, worklist);
        }
        Expression::Set { values } | Expression::Tuple { values } => {
            dispose_expressions(mem::take(values), budget, worklist)
        }
        Expression::Record { fields } | Expression::RecordSet { fields } => {
            dispose_fields(mem::take(fields), budget, worklist)
        }
        Expression::At { target, key } => {
            detach_boxed(target, budget, worklist);
            detach_boxed(key, budget, worklist);
        }
        Expression::Update { target, updates } => {
            detach_boxed(target, budget, worklist);
            for update in mem::take(updates) {
                dispose_update(update, budget, worklist);
            }
        }
        Expression::Forall { bounds, body }
        | Expression::Exists { bounds, body }
        | Expression::Function { bounds, body }
        | Expression::Filter { bounds, body }
        | Expression::MapSet { bounds, body } => {
            detach_bindings(bounds, budget, worklist);
            detach_boxed(body, budget, worklist);
        }
        Expression::Choose { binding, body } => {
            detach_domain(&mut binding.domain, budget, worklist);
            detach_boxed(body, budget, worklist);
        }
        Expression::Fold {
            initial,
            collection,
            body,
            ..
        } => {
            detach_boxed(initial, budget, worklist);
            detach_boxed(collection, budget, worklist);
            detach_boxed(body, budget, worklist);
        }
        Expression::SelectSeq { sequence, body, .. }
        | Expression::SortSeq { sequence, body, .. } => {
            detach_boxed(sequence, budget, worklist);
            detach_boxed(body, budget, worklist);
        }
        Expression::Assert { condition, message } => {
            detach_boxed(condition, budget, worklist);
            detach_boxed(message, budget, worklist);
        }
        Expression::Domain { argument }
        | Expression::VariantTag { argument }
        | Expression::Cardinality { argument }
        | Expression::SequenceSet { argument }
        | Expression::Len { argument }
        | Expression::Head { argument }
        | Expression::Tail { argument }
        | Expression::Powerset { argument }
        | Expression::Union { argument }
        | Expression::Prime { argument }
        | Expression::Not { argument }
        | Expression::Neg { argument } => detach_boxed(argument, budget, worklist),
        Expression::Cup { left, right }
        | Expression::Cap { left, right }
        | Expression::Difference { left, right }
        | Expression::SubsetEq { left, right }
        | Expression::Append { left, right }
        | Expression::Concat { left, right }
        | Expression::FunctionSet { left, right }
        | Expression::FunctionIn { left, right }
        | Expression::SequenceIn { left, right }
        | Expression::Add { left, right }
        | Expression::Sub { left, right }
        | Expression::Mul { left, right }
        | Expression::Div { left, right }
        | Expression::Mod { left, right }
        | Expression::Pow { left, right }
        | Expression::Eq { left, right }
        | Expression::Ne { left, right }
        | Expression::Lt { left, right }
        | Expression::Le { left, right }
        | Expression::Gt { left, right }
        | Expression::Ge { left, right }
        | Expression::And { left, right }
        | Expression::Or { left, right }
        | Expression::Implies { left, right } => {
            detach_boxed(left, budget, worklist);
            detach_boxed(right, budget, worklist);
        }
        Expression::Subseq { sequence, from, to } => {
            detach_boxed(sequence, budget, worklist);
            detach_boxed(from, budget, worklist);
            detach_boxed(to, budget, worklist);
        }
        Expression::If {
            condition,
            consequent,
            alternative,
        } => {
            detach_boxed(condition, budget, worklist);
            detach_boxed(consequent, budget, worklist);
            detach_boxed(alternative, budget, worklist);
        }
        Expression::Enabled {
            branches,
            subscript,
        } => {
            dispose_branches(mem::take(branches), budget, worklist);
            if let Some(child) = subscript.take() {
                dispose_expression(*child, budget, worklist);
            }
        }
        Expression::In { value, domain } => {
            detach_boxed(value, budget, worklist);
            detach_domain(domain, budget, worklist);
        }
    }
}

fn detach_formula(node: &mut TemporalFormula, budget: usize, worklist: &mut Worklist) {
    match node {
        TemporalFormula::Call {
            arguments,
            captures,
            ..
        } => {
            dispose_expressions(mem::take(arguments), budget, worklist);
            dispose_expressions(mem::take(captures), budget, worklist);
        }
        TemporalFormula::Frame {
            arguments,
            captures,
            formula,
            ..
        } => {
            dispose_expressions(mem::take(arguments), budget, worklist);
            dispose_expressions(mem::take(captures), budget, worklist);
            detach_boxed_formula(formula, budget, worklist);
        }
        TemporalFormula::Atom { expression } => detach_boxed(expression, budget, worklist),
        TemporalFormula::Not { formula }
        | TemporalFormula::Always { formula }
        | TemporalFormula::Eventually { formula } => {
            detach_boxed_formula(formula, budget, worklist)
        }
        TemporalFormula::And { left, right } | TemporalFormula::Or { left, right } => {
            detach_boxed_formula(left, budget, worklist);
            detach_boxed_formula(right, budget, worklist);
        }
        TemporalFormula::Forall { bounds, formula }
        | TemporalFormula::Exists { bounds, formula } => {
            detach_bindings(bounds, budget, worklist);
            detach_boxed_formula(formula, budget, worklist);
        }
    }
}

fn release(detach: impl FnOnce(&mut Worklist)) {
    let mut worklist = Worklist::new();
    detach(&mut worklist);
    while let Some(detached) = worklist.pop() {
        match detached {
            Detached::Expression(mut node) => {
                detach_expression(&mut node, DEPTH_BUDGET, &mut worklist)
            }
            Detached::Branch(mut node) => detach_branch(&mut node, DEPTH_BUDGET, &mut worklist),
            Detached::Formula(mut node) => detach_formula(&mut node, DEPTH_BUDGET, &mut worklist),
            Detached::Value(mut node) => detach_value(&mut node, DEPTH_BUDGET, &mut worklist),
        }
    }
}

#[inline(never)]
fn release_value(value: &mut Value) {
    release(|worklist| detach_value(value, DEPTH_BUDGET, worklist));
}

impl Drop for Expression {
    fn drop(&mut self) {
        if !is_leaf_expression(self) {
            release(|worklist| detach_expression(self, DEPTH_BUDGET, worklist));
        }
    }
}

impl Drop for Branch {
    fn drop(&mut self) {
        if !is_leaf_branch(self) {
            release(|worklist| detach_branch(self, DEPTH_BUDGET, worklist));
        }
    }
}

impl Drop for TemporalFormula {
    fn drop(&mut self) {
        if !is_leaf_formula(self) {
            release(|worklist| detach_formula(self, DEPTH_BUDGET, worklist));
        }
    }
}

impl Drop for Value {
    #[inline]
    fn drop(&mut self) {
        if !is_shallow_value(self) {
            release_value(self);
        }
    }
}
